Python, table-driven; illegal moves raise.

```python
from enum import Enum


class OrderState(Enum):
    CREATED = "created"
    PAID = "paid"
    SHIPPED = "shipped"
    DELIVERED = "delivered"
    CANCELLED = "cancelled"
    REFUNDED = "refunded"


TRANSITIONS = {
    OrderState.CREATED:   {OrderState.PAID, OrderState.CANCELLED},
    OrderState.PAID:      {OrderState.SHIPPED, OrderState.REFUNDED},
    OrderState.SHIPPED:   {OrderState.DELIVERED},
    OrderState.DELIVERED: {OrderState.REFUNDED},
    OrderState.CANCELLED: set(),
    OrderState.REFUNDED:  set(),
}


class InvalidTransition(Exception):
    pass


class Order:
    def __init__(self, order_id):
        self.id = order_id
        self.state = OrderState.CREATED
        self.history = [OrderState.CREATED]

    def can(self, target):
        return target in TRANSITIONS[self.state]

    def transition(self, target):
        if not self.can(target):
            raise InvalidTransition(f"{self.id}: {self.state.value} -> {target.value} not allowed")
        self.state = target
        self.history.append(target)

    def pay(self):      self.transition(OrderState.PAID)
    def ship(self):     self.transition(OrderState.SHIPPED)
    def deliver(self):  self.transition(OrderState.DELIVERED)
    def cancel(self):   self.transition(OrderState.CANCELLED)
    def refund(self):   self.transition(OrderState.REFUNDED)


if __name__ == "__main__":
    o = Order("A1")
    o.pay(); o.ship(); o.deliver(); o.refund()
    print([s.value for s in o.history])  # created, paid, shipped, delivered, refunded

    try:
        Order("A2").ship()
    except InvalidTransition as e:
        print(e)  # A2: created -> shipped not allowed
```

Rules chosen: cancel only before payment (paid orders exit via refund, since money moved); refund after payment or delivery; no refund while in transit; cancelled/refunded terminal. Change the `TRANSITIONS` table to alter policy.
